from __future__ import annotations

import csv
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "output" / "b2_autonomous_capability_expansion_fresh_v1" / "analysis"
OUT.mkdir(parents=True, exist_ok=True)

B2_IDS = [2, 7, 11, 16, 17, 18, 19, 28, 32, 61, 64, 65, 68, 71, 73, 80, 82, 84, 89, 94]
EXCLUDED = {2, 82}
EFFECTIVE = [q for q in B2_IDS if q not in EXCLUDED]
STRUCTURE = [7, 11, 16, 17, 65, 71, 80, 84]
SOURCE_BLOCKED = [18, 28, 32, 61, 64, 68, 73, 94]
CONDITION = [19, 89, 94]


def write_csv(name: str, rows: list[dict], fields: list[str]) -> None:
    with (OUT / name).open("w", encoding="utf-8-sig", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)


def load_jsonl(path: Path) -> list[dict]:
    if not path.exists():
        return []
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def qmap(rows: list[dict]) -> dict[int, dict]:
    return {int(row["question_id"]): row for row in rows if str(row.get("question_id", "")).isdigit()}


def main() -> None:
    valid_dir = ROOT / "data/output/b2_autonomous_capability_expansion_valid_final_v1"
    test_dir = ROOT / "data/output/b2_autonomous_capability_expansion_test_final_v1"
    targeted_dir = ROOT / "data/output/b2_schedule_condition_targeted_v7"
    valid_results = qmap(load_jsonl(valid_dir / "answer_results.jsonl"))
    test_results = qmap(load_jsonl(test_dir / "answer_results.jsonl"))
