    write_csv("b2_fix_candidates.csv", [{"fix_id": "fix_001", "fix_name": "deterministic_schedule_condition_and_evidence_presence", "target_question_ids": "19,89", "source_correctness_rate": 1.0, "downstream_reachability_rate": 1.0, "implementation_size": "small", "incorrect_answer_risk": "low", "regression_risk": "low", "status": "accepted"}, {"fix_id": "fix_002", "fix_name": "structure_format_localization", "target_question_ids": "7,11,16,17,65,71,80,84", "source_correctness_rate": 0.5, "downstream_reachability_rate": 0.0, "implementation_size": "medium", "incorrect_answer_risk": "medium", "regression_risk": "medium", "status": "deferred"}, {"fix_id": "fix_003", "fix_name": "source_content_recovery", "target_question_ids": "18,28,32,61,64,68,73,94", "source_correctness_rate": 0.25, "downstream_reachability_rate": 0.0, "implementation_size": "medium+", "incorrect_answer_risk": "high", "regression_risk": "medium", "status": "deferred"}], ["fix_id", "fix_name", "target_question_ids", "source_correctness_rate", "downstream_reachability_rate", "implementation_size", "incorrect_answer_risk", "regression_risk", "status"])
    write_csv("b2_cost_benefit.csv", [{"fix_id": "fix_001", "impact_score": 4, "implementation_cost_score": 1, "incorrect_risk_score": 1, "regression_risk_score": 1, "confidence_score": 5, "priority_score": 10.0, "expected_gate_candidate_gain": 2}, {"fix_id": "fix_002", "impact_score": 3, "implementation_cost_score": 3, "incorrect_risk_score": 3, "regression_risk_score": 3, "confidence_score": 2, "priority_score": 0.67, "expected_gate_candidate_gain": 0}, {"fix_id": "fix_003", "impact_score": 2, "implementation_cost_score": 4, "incorrect_risk_score": 4, "regression_risk_score": 3, "confidence_score": 2, "priority_score": 0.18, "expected_gate_candidate_gain": 0}], ["fix_id", "impact_score", "implementation_cost_score", "incorrect_risk_score", "regression_risk_score", "confidence_score", "priority_score", "expected_gate_candidate_gain"])
